#include "CKern.h"
#include "CMatrix.h"
#include "CIvm.h"

// Reference checks for the IVM against fixtures generated by the MATLAB toolbox.
//
// With _NDLMATLAB the reference IVM (kernel, noise and ivmInfo structs) is loaded
// straight from matfiles/testIvm<Type>.mat.  Without MATLAB the same reference
// (active set I, and the sparse posterior terms m and beta) is read as plain numeric
// matrices from matfiles/testIvm<Type>Active.mat (extracted from ivmInfoInit), so the
// test runs under libmatio.

int testGaussian();
int testProbit();
int testNcnm();

int main()
{
  int fail = 0;
  fail += testGaussian();
  // ordered IVM: deferred (see backlog macos-ordered-categorical-noise).
  fail += testProbit();
  fail += testNcnm();
  cout << "Number of failures: " << fail << endl;
  return fail > 0 ? 1 : 0;
}

static string fixture(const string& name)
{
  return "matfiles" + ndlstrutil::dirSep() + name + ".mat";
}

// Stream write, read back, and compare.
static int testStreamRoundTrip(const CIvm& model)
{
  model.toFile("crap_ivm");
  CIvm* reread = readIvmFromFile("crap_ivm", 0);
  int fail = 0;
  if(model.equals(*reread))
    cout << "Stream read and write " << model.getNoiseName() << " Noise IVM passed." << endl;
  else
  {
    cout << "FAILURE: " << "Stream read and write " << model.getNoiseName() << " Noise IVM." << endl;
    cout << "Written model: " << endl;
    model.display(cout);
    cout << "Read in model: " << endl;
    reread->display(cout);
    fail++;
  }
  delete reread;
  return fail;
}

#ifndef _NDLMATLAB
// Compare the selected active set, m and beta of a freshly trained IVM with the
// numeric reference in <type>Active.mat.  I is 1-based, m and beta are numData x 1
// with non-zeros only at active points.
static int checkAgainstReference(const CIvm& model, const string& type)
{
  const string file = fixture("testIvm" + type + "Active");
  CMatrix I, m, beta;
  I.readMatlabFile(file.c_str(), "I");
  m.readMatlabFile(file.c_str(), "m");
  beta.readMatlabFile(file.c_str(), "beta");

  int fail = 0;
  if(model.getNumActive() != I.getRows())
  {
    cout << "FAILURE: " << type << " IVM active set size " << model.getNumActive()
         << " != reference " << I.getRows() << "." << endl;
    return 1;
  }
  for(unsigned int i = 0; i < model.getNumActive(); i++)
  {
    unsigned int ref = (unsigned int)I.getVal(i) - 1;
    if(model.getActivePoint(i) != ref)
    {
      cout << "FAILURE: " << type << " IVM active point " << i << " is "
           << model.getActivePoint(i) << ", reference " << ref << "." << endl;
      fail++;
      continue;
    }
    for(unsigned int j = 0; j < model.m.getCols(); j++)
    {
      if(fabs(model.m.getVal(i, j) - m.getVal(ref, j)) > ndlutil::MATCHTOL)
      {
        cout << "FAILURE: " << type << " IVM m(" << i << "," << j << ") = "
             << model.m.getVal(i, j) << ", reference " << m.getVal(ref, j) << "." << endl;
        fail++;
      }
      double bm = model.beta.getVal(i, j);
      double br = beta.getVal(ref, j);
      if(fabs(bm - br) > ndlutil::MATCHTOL * (1.0 + fabs(br)))
      {
        cout << "FAILURE: " << type << " IVM beta(" << i << "," << j << ") = "
             << bm << ", reference " << br << "." << endl;
        fail++;
      }
    }
  }
  if(fail == 0)
    cout << model.getNoiseName() << " Noise IVM matches numeric reference." << endl;
  return fail;
}
#endif /* not _NDLMATLAB */

int testGaussian()
{
  int fail = 0;
  CMatrix X;
  X.readMatlabFile(fixture("testIvmGaussian").c_str(), "X");
  CMatrix y;
  y.readMatlabFile(fixture("testIvmGaussian").c_str(), "y");

  CCmpndKern kernInit(X);
  kernInit.addKern(new CRbfKern(X));
  kernInit.addKern(new CLinKern(X));
  kernInit.addKern(new CBiasKern(X));
  kernInit.addKern(new CWhiteKern(X));
  CGaussianNoise noiseInit(&y);
  
  CIvm modelInit(&X, &y, &kernInit, &noiseInit, CIvm::ENTROPY, 50);
  modelInit.selectPoints();
   
#ifdef _NDLMATLAB
  CCmpndKern kern(X);
  kern.readMatlabFile(fixture("testIvmGaussian"), "kernInit");
  CGaussianNoise noise(&y);
  noise.readMatlabFile(fixture("testIvmGaussian"), "noiseInit");

  CIvm model(&X, &y, &kern, &noise, fixture("testIvmGaussian"), "ivmInfoInit", 0);
  if(model.equals(modelInit))
    cout << model.getNoiseName() << " Noise IVM passed." << endl;
  else
  {
    cout << "FAILURE: " << model.getNoiseName() << " Noise IVM." << endl;
    fail++;
  }
#else
  fail += checkAgainstReference(modelInit, "Gaussian");
#endif
  fail += testStreamRoundTrip(modelInit);
  return fail;
}

